#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>

void *worker_function(void *arg) {
    int old_state;
    int rc;

    printf("Worker: Starting. Default cancel state is ENABLED.\n");

    // 1. Enter Critical Section: Disable Cancellation
    rc = pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, &old_state);
    if (rc != 0) {
        fprintf(stderr, "Worker: Error setting cancel state: %d\n", rc);
        return NULL;
    }
    printf("Worker: Cancellation DISABLED. (Old state saved.)\n");

    // Simulate critical work while safely ignoring external cancellation requests
    printf("Worker: Performing critical work (5 seconds)... Request will be blocked.\n");
    sleep(5); 

    // 2. Exit Critical Section: Re-enable Cancellation
    rc = pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, &old_state);
    if (rc != 0) {
        fprintf(stderr, "Worker: Error re-enabling cancel state: %d\n", rc);
        return NULL;
    }
    printf("Worker: Cancellation RE-ENABLED.\n");

    // Check for pending cancellation requests immediately after enabling
    pthread_testcancel(); 

    // If thread was not canceled above, it proceeds
    printf("Worker: Finished work normally.\n");
    return (void*)0;
}

int main() {
    pthread_t thread_id;
    void *res;
    int rc;

    if (pthread_create(&thread_id, NULL, worker_function, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    // Wait for the worker to enter the critical disabled state
    sleep(1); 

    printf("Main: Attempting to cancel the worker thread.\n");
    rc = pthread_cancel(thread_id);
    if (rc != 0) {
        fprintf(stderr, "Main: Error canceling thread: %d\n", rc);
    }

    // Join the thread
    if (pthread_join(thread_id, &res) != 0) {
        perror("pthread_join");
        return 1;
    }

    if (res == PTHREAD_CANCELED) {
        printf("Main: Thread was successfully canceled AFTER enabling it.\n");
    } else {
        printf("Main: Thread finished normally.\n");
    }

    return 0;
}
